const AFTER_HELP: &str = help_section!("after help", "cksum.md");

#[derive(Debug, PartialEq)]
enum OutputFormat {
    Hexadecimal,
    Raw,
    Base64,
}

struct Options {
    algo_name: String,
    tag: bool, // will cover the --untagged option
    length: Option<usize>,
    output_format: OutputFormat,
    asterisk: bool, // if we display an asterisk or not (--binary/--text)
}

/// Calculate checksum
///
/// # Arguments
///
/// * `options` - CLI options for the assigning checksum algorithm
/// * `files` - A iterator of OsStr which is a bunch of files that are using for calculating checksum
#[allow(clippy::cognitive_complexity)]
#[allow(clippy::too_many_lines)]
fn cksum<'a, I>(options: Options, files: I) -> UResult<()>
where
    I: Iterator<Item = &'a OsStr>,
{
    let algo = detect_algo(&options.algo_name, options.length)?;
    let algo_name = algo.name;
    let mut digest: Box<dyn Digest + 'static> = (algo.create_fn)();
    let output_bits = algo.bits;

    let files: Vec<_> = files.collect();
    if options.output_format == OutputFormat::Raw && files.len() > 1 {
        return Err(Box::new(ChecksumError::RawMultipleFiles));
    }

    for filename in files {
        let filename = Path::new(filename);
        let stdin_buf;
        let file_buf;
        let not_file = filename == OsStr::new("-");

        let mut file = BufReader::new(if not_file {
            stdin_buf = stdin();
            Box::new(stdin_buf) as Box<dyn Read>
        } else if filename.is_dir() {
            Box::new(BufReader::new(io::empty())) as Box<dyn Read>
        } else {
            file_buf = match File::open(filename) {
                Ok(opened) => opened,
                Err(err) => {
                    show!(err.map_err_context(|| filename.to_string_lossy().to_string()));
                    continue;
                }
            };
            Box::new(file_buf) as Box<dyn Read>
        });

        if filename.is_dir() {
            show!(USimpleError::new(
                1,
                format!("{}: Is a directory", filename.display())
            ));
            continue;
        }

        digest.reset();
        let mut digest_writer = DigestWriter::new(&mut digest, false);
        let mut buffer = [0u8; 8192];
        let mut output_size = 0usize;
        loop {
            match file.read(&mut buffer) {
                Ok(0) => {
                    digest_writer.finalize();
                    if digest.output_bits() > 0 {
                        let sum_hex = digest.result_str();
                        let sz = output_size;
                        if options.output_format == OutputFormat::Raw {
                            let bytes = match algo_name {
                                ALGORITHM_OPTIONS_CRC => {
                                    sum_hex.parse::<u32>().unwrap().to_be_bytes().to_vec()
                                }
                                ALGORITHM_OPTIONS_SYSV | ALGORITHM_OPTIONS_BSD => {
                                    sum_hex.parse::<u16>().unwrap().to_be_bytes().to_vec()
                                }
                                _ => hex::decode(sum_hex).unwrap(),
                            };
                            stdout().write_all(&bytes)?;
                            return Ok(());
                        } else {
                            let sum = if options.output_format == OutputFormat::Base64 {
                                if algo_name == ALGORITHM_OPTIONS_CRC
                                    || algo_name == ALGORITHM_OPTIONS_SYSV
                                    || algo_name == ALGORITHM_OPTIONS_BSD
                                {
                                    sum_hex
                                } else {
                                    match hex::decode(&sum_hex) {
                                        Ok(digest_bytes) => encoding::encode(
                                            encoding::Format::Base64,
                                            &digest_bytes,
                                        )
                                        .unwrap(),
                                        Err(_) => encoding::encode(
                                            encoding::Format::Base64,
                                            &hex::decode(&sum_hex).unwrap(),
                                        )
                                        .unwrap(),
                                    }
                                }
                            } else {
                                sum_hex
                            };

                            let bsd_width = 5;
                            let mut before_filename = String::new();
                            let mut should_print_filename = false;
                            let mut after_filename = String::new();

                            if algo_name == ALGORITHM_OPTIONS_SYSV {
                                match sum.parse::<u16>() {
                                    Ok(value) => {
                                        let blocks = (sz + output_bits - 1) / output_bits;
                                        if not_file {
                                            before_filename = format!("{value} {blocks}");
                                            should_print_filename = false;
                                            after_filename.clear();
                                        } else {
                                            before_filename = format!("{value} {blocks} ");
                                            should_print_filename = true;
                                            after_filename.clear();
                                        }
                                    }
                                    Err(_) => {
                                        let _ = sum.parse::<u16>().unwrap();
                                    }
                                }
                            } else if algo_name == ALGORITHM_OPTIONS_BSD {
                                match sum.parse::<u16>() {
                                    Ok(value) => {
                                        let blocks = (sz + output_bits - 1) / output_bits;
                                        if not_file {
                                            before_filename =
                                                format!("{value:0bsd_width$} {blocks:bsd_width$}");
                                            should_print_filename = false;
                                            after_filename.clear();
                                        } else {
                                            before_filename =
                                                format!("{value:0bsd_width$} {blocks:bsd_width$} ");
                                            should_print_filename = true;
                                            after_filename.clear();
                                        }
                                    }
                                    Err(_) => {
                                        let _ = sum.parse::<u16>().unwrap();
                                    }
                                }
                            } else if algo_name == ALGORITHM_OPTIONS_CRC {
                                if not_file {
                                    before_filename = format!("{sum} {sz}");
                                    should_print_filename = false;
                                    after_filename.clear();
                                } else {
                                    before_filename = format!("{sum} {sz} ");
                                    should_print_filename = true;
                                    after_filename.clear();
                                }
                            } else if algo_name == ALGORITHM_OPTIONS_BLAKE2B {
                                if options.tag {
                                    if let Some(length) = options.length {
                                        before_filename = format!("BLAKE2b-{} (", length * 8);
                                        should_print_filename = true;
                                        after_filename = format!(") = {sum}");
                                    } else {
                                        before_filename = "BLAKE2b (".to_owned();
                                        should_print_filename = true;
                                        after_filename = format!(") = {sum}");
                                    }
                                } else if options.asterisk {
                                    before_filename = format!("{sum} *");
                                    should_print_filename = true;
                                    after_filename.clear();
                                } else {
                                    before_filename = format!("{sum}  ");
                                    should_print_filename = true;
                                    after_filename.clear();
                                }
                            } else if algo_name == ALGORITHM_OPTIONS_MD5
                                || algo_name == ALGORITHM_OPTIONS_SHA1
                                || algo_name == ALGORITHM_OPTIONS_SHA224
                                || algo_name == ALGORITHM_OPTIONS_SHA256
                                || algo_name == ALGORITHM_OPTIONS_SHA384
                                || algo_name == ALGORITHM_OPTIONS_SHA512
                                || algo_name == ALGORITHM_OPTIONS_BLAKE3
                                || algo_name == ALGORITHM_OPTIONS_SM3
                            {
                                if options.tag {
                                    before_filename =
                                        format!("{} (", algo_name.to_ascii_uppercase());
                                    should_print_filename = true;
                                    after_filename = format!(") = {sum}");
                                } else if options.asterisk {
                                    before_filename = format!("{sum} *");
                                    should_print_filename = true;
                                    after_filename.clear();
                                } else {
                                    before_filename = format!("{sum}  ");
                                    should_print_filename = true;
                                    after_filename.clear();

